const fs = require('fs');
const path = require('path');

const stateFile = '/home/node/shared/.telegram-style-pending.json';

function loadPending() {
  try {
    return JSON.parse(fs.readFileSync(stateFile, 'utf8'));
  } catch {
    return {};
  }
}

function savePending(p) {
  try {
    fs.mkdirSync(path.dirname(stateFile), { recursive: true });
    fs.writeFileSync(stateFile, JSON.stringify(p, null, 2), 'utf8');
  } catch (e) {}
}

const raw = $input.first().json;
const data = raw.body !== undefined ? raw.body : raw;
const msg = data.message;
if (!msg || !msg.chat) {
  return [{ json: { reply: 'Нет message', chat_id: null, skip: true } }];
}

const chatId = String(msg.chat.id);
const textRaw = (msg.text || msg.caption || '').trim();

const styleOnly = textRaw.match(/^\/style_(tomas|misha|yulya|nasik)(@\S+)?\s*$/);
if (styleOnly && !msg.forward_date) {
  const pending = loadPending();
  pending[chatId] = styleOnly[1];
  savePending(pending);
  return [{
    json: {
      reply: 'Ок. Перешли пост (Forward) — добавлю в этот стиль.',
      chat_id: msg.chat.id,
    },
  }];
}

const forwarded =
  msg.forward_from != null ||
  msg.forward_from_chat != null ||
  msg.forward_date != null;
if (!forwarded) {
  return [{
    json: {
      reply:
        'Перешли сообщение через Forward. Или сначала: /style_tomas, /style_misha, /style_yulya, /style_nasik',
      chat_id: msg.chat.id,
    },
  }];
}

let blogger = null;
const cmdInText = textRaw.match(/^\/style_(tomas|misha|yulya|nasik)(@\S+)?\s*(\n|$)/);
if (cmdInText) blogger = cmdInText[1];

if (!blogger) {
  const pending = loadPending();
  blogger = pending[chatId];
}

const envMap = [
  [process.env.TELEGRAM_STYLE_CHAT_TOMAS, 'tomas'],
  [process.env.TELEGRAM_STYLE_CHAT_MISHA, 'misha'],
  [process.env.TELEGRAM_STYLE_CHAT_YULYA, 'yulya'],
  [process.env.TELEGRAM_STYLE_CHAT_NASIK, 'nasik'],
];
if (!blogger) {
  for (const [id, b] of envMap) {
    if (id && String(id) === chatId) {
      blogger = b;
      break;
    }
  }
}

if (!blogger) {
  return [{
    json: {
      reply:
        'Не выбран блогер: добавь в начало /style_tomas (или /style_misha, /style_yulya, /style_nasik), либо отправь команду отдельным сообщением перед пересылкой.',
      chat_id: msg.chat.id,
    },
  }];
}

const pend = loadPending();
delete pend[chatId];
savePending(pend);

let body = textRaw.replace(/^\/style_(tomas|misha|yulya|nasik)(@\S+)?\s*\n?/, '').trim();
if (!body) {
  body = '[медиа без текста — перешли текстовый пост или добавь подпись]';
}

const names = {
  tomas: 'Томаса',
  misha: 'Миши',
  yulya: 'Юли',
  nasik: 'Насика',
};

const filePath = path.join('/home/node/shared/bloggers', blogger, 'brand', 'style-examples.md');
let content = fs.readFileSync(filePath, 'utf8');
const matches = content.match(/^## Пример \d+$/gm);
const n = (matches ? matches.length : 0) + 1;
const block = '\n## Пример ' + n + '\n' + body + '\n';
if (content.trimEnd().endsWith('---')) {
  content = content.replace(/\n---\s*$/, '') + block + '\n---\n';
} else {
  content = content.trimEnd() + block;
}
fs.writeFileSync(filePath, content, 'utf8');

return [{
  json: {
    reply: 'Добавлено в стиль ' + names[blogger],
    chat_id: msg.chat.id,
  },
}];
